import { ChannelHub } from './solution';

function ok(value: boolean, message: string): void {
  if (!value) throw new Error(message);
}

function equal<T>(actual: T, expected: T, message: string): void {
  if (actual !== expected) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}

function throwsTypeError(fn: () => void, message: string): void {
  try {
    fn();
  } catch (error) {
    if (error instanceof TypeError) return;
    throw new Error(`${message}: wrong error type`);
  }
  throw new Error(`${message}: did not throw`);
}

const hub = new ChannelHub<{ value: number }>();
const calls: string[] = [];
const payload = { value: 7 };
const listener = (received: { value: number }): void => {
  ok(received === payload, 'payload must pass through unchanged');
  calls.push('duplicate');
};
const first = hub.attach('news', received => {
  ok(received === payload, 'first listener receives original payload');
  calls.push('first');
});
const second = hub.attach('news', listener);
const third = hub.attach('news', listener);
ok(first > 0 && second > 0 && third > 0, 'tokens must be positive');
ok(first !== second && first !== third && second !== third, 'tokens must be unique');
equal(hub.publish('news', payload), 3, 'publish count');
equal(calls.join(','), 'first,duplicate,duplicate', 'registration order and duplicates');
ok(hub.detach('news', second), 'matching registration must detach');
ok(!hub.detach('news', second), 'detaching twice must report false');
ok(!hub.detach('other', third), 'channel and token must both match');
calls.length = 0;
equal(hub.publish('news', payload), 2, 'remaining listener count');
equal(calls.join(','), 'first,duplicate', 'only selected registration is removed');
equal(hub.publish('missing', payload), 0, 'unknown channel publishes to zero listeners');

const spacedCalls: string[] = [];
hub.attach(' room ', () => spacedCalls.push('spaced'));
hub.attach('room', () => spacedCalls.push('plain'));
equal(hub.publish(' room ', payload), 1, 'untrimmed channel identity is preserved');
equal(spacedCalls.join(','), 'spaced', 'distinct valid names remain distinct');

const snapshotHub = new ChannelHub<number>();
const snapshotCalls: string[] = [];
let lateToken = 0;
const removable = (): void => snapshotCalls.push('removable');
snapshotHub.attach('c', () => {
  snapshotCalls.push('first');
  snapshotHub.detach('c', lateToken);
  snapshotHub.attach('c', () => snapshotCalls.push('attached-later'));
});
lateToken = snapshotHub.attach('c', removable);
equal(snapshotHub.publish('c', 1), 2, 'snapshot includes listeners removed during publication');
equal(snapshotCalls.join(','), 'first,removable', 'snapshot excludes listeners attached during publication');
snapshotCalls.length = 0;
equal(snapshotHub.publish('c', 2), 2, 'later publication sees mutations');
equal(snapshotCalls.join(','), 'first,attached-later', 'later snapshot has updated registrations');

equal(snapshotHub.clear('c'), 3, 'clear returns all current registrations');
equal(snapshotHub.clear('c'), 0, 'clearing empty channel returns zero');
equal(snapshotHub.publish('c', 3), 0, 'clear removes listeners');

const throwingHub = new ChannelHub<number>();
const boom = new Error('boom');
let afterThrow = false;
throwingHub.attach('x', () => { throw boom; });
throwingHub.attach('x', () => { afterThrow = true; });
try {
  throwingHub.publish('x', 1);
  throw new Error('throwing listener was not propagated');
} catch (error) {
  ok(error === boom, 'the exact listener error must propagate');
}
ok(!afterThrow, 'publication must stop after a listener throws');

for (const invalid of ['', ' ', '\t\n']) {
  throwsTypeError(() => hub.attach(invalid, () => undefined), 'attach rejects blank channel');
  throwsTypeError(() => hub.detach(invalid, first), 'detach rejects blank channel');
  throwsTypeError(() => hub.clear(invalid), 'clear rejects blank channel');
  throwsTypeError(() => hub.publish(invalid, payload), 'publish rejects blank channel');
}

